//! Exact scalar-only K24 consumers for the two retained hidden ledgers.
#![allow(dead_code)]
mod fold {
include!("../unaudited-codex-orbit0-filtered-k18-charge-2026-08-23/run_k18_charge.rs");

use std::collections::BTreeMap;
use std::fs::{metadata,rename,File};
use std::io::{BufReader,Read,Seek,SeekFrom};

const H18_INPUT:&str="computations/unaudited-codex-orbit0-hidden-k16-k2-full-orbit-2026-08-23/checkpoint_k18_22_pivotable.bin";
const H18_SHA:&str="442f4220e7f224b9961c8236fff918c6274337e672b5cf5e62c87614b53044c8";
const H18_N:u64=158_439_965;
const PAIR_INPUT:&str="computations/unaudited-codex-orbit0-hidden-k16-k2-full-orbit-2026-08-23/hidden_k16_decorated_pair_orbits_full.bin";
const PAIR_SHA:&str="22f91fc887caecb628df495b6a19e319c0ada39b6940b1ca4f795ae09d6c21c8";
const PAIR_N:u64=101_545_723;
const CACHE_CAP:usize=400_000;
const U:i128=400_591_699_200;

#[derive(Clone,Copy)]struct H18{row:Row,weight:i128,witness:Row,p2:u8,t2:u8,uses:u64,orbit:u16,stabilizer:u16,m2:u8}
fn dh18(r:&[u8;80])->H18{let mut row=[0;24];row.copy_from_slice(&r[..24]);let mut w=[0;24];w.copy_from_slice(&r[40..64]);assert_eq!(r[78],1);H18{row:Row(row),weight:i128::from_le_bytes(r[24..40].try_into().unwrap()),witness:Row(w),p2:r[64],t2:r[65],uses:u64::from_le_bytes(r[66..74].try_into().unwrap()),orbit:u16::from_le_bytes(r[74..76].try_into().unwrap()),stabilizer:u16::from_le_bytes(r[76..78].try_into().unwrap()),m2:r[79]}}
#[derive(Clone,Copy,Eq,Ord,PartialEq,PartialOrd)]struct PairKey{row:Row,pivot:u8}
#[derive(Clone,Copy)]struct Pair{key:PairKey,weight:i128,uses:u64,orbit:u16,stabilizer:u16}
fn dpair(r:&[u8;53])->Pair{let mut row=[0;24];row.copy_from_slice(&r[..24]);Pair{key:PairKey{row:Row(row),pivot:r[24]},weight:i128::from_le_bytes(r[25..41].try_into().unwrap()),uses:u64::from_le_bytes(r[41..49].try_into().unwrap()),orbit:u16::from_le_bytes(r[49..51].try_into().unwrap()),stabilizer:u16::from_le_bytes(r[51..53].try_into().unwrap())}}

#[derive(Clone,Default)]struct HStat{records:u64,uses:u64,source:i128,l1:i128,first_pivots:u64,first_tails:u64,pivotable:u64,final_pivots:u64,terminal:u64,charge:i128,hits:u64,misses:u64,clears:u64,peak:usize,hist:BTreeMap<(u8,u8),u64>,samples:BTreeMap<usize,(u64,String)>}
impl HStat{fn add(&mut self,x:HStat){self.records+=x.records;self.uses+=x.uses;self.source+=x.source;self.l1+=x.l1;self.first_pivots+=x.first_pivots;self.first_tails+=x.first_tails;self.pivotable+=x.pivotable;self.final_pivots+=x.final_pivots;self.terminal+=x.terminal;self.charge+=x.charge;self.hits+=x.hits;self.misses+=x.misses;self.clears+=x.clears;self.peak=self.peak.max(x.peak);for(k,v)in x.hist{*self.hist.entry(k).or_default()+=v}for(k,v)in x.samples{let z=self.samples.entry(k).or_insert_with(||v.clone());if v.0<z.0{*z=v}}}}
#[derive(Clone,Copy,Eq,Hash,PartialEq)]struct SKey{sig:[u8;12],pivot:u8,degree:u8}
#[derive(Clone)]struct Choice{tail:u8,sig:[u8;12],pivots:Vec<usize>}
fn choices(s:[u8;12],p:usize,d:usize,e:&E)->Vec<Choice>{let ts:&[[u8;4]]=match d{2=>&e.tails[p][0],4=>&e.tails[p][2],_=>unreachable!()};ts.iter().enumerate().filter_map(|(ti,t)|{let z=child_sig(s,p,t,e);let ps=avail(z,e);(!ps.is_empty()).then_some(Choice{tail:ti as u8,sig:z,pivots:ps})}).collect()}
fn hx(r:&Row)->String{r.0.iter().map(|x|format!("{:02x}",x)).collect()}
fn hmap(x:&BTreeMap<(u8,u8),u64>)->String{x.iter().map(|(&(a,b),n)|format!("\"{}_{}\":{}",a,b,n)).collect::<Vec<_>>().join(",")}
fn bin(i:u64,n:u64)->usize{((i*257/n).min(256))as usize}
fn terminal4(row:&Row,s:[u8;12],p:usize,e:&E,cache:&mut HashMap<RKey,(i64,i64,u64,u64)>,st:&mut HStat)->(i64,i64,u64,u64){if cache.len()>=CACHE_CAP{st.peak=st.peak.max(cache.len());cache.clear();st.clears+=1}let key=RKey{profile:profile(row,p,e),sig:s,pivot:p as u8,degree:4};let z=if let Some(&z)=cache.get(&key){st.hits+=1;z}else{st.misses+=1;resp(row,s,p,4,e,cache)};assert_eq!((z.2,z.3),(60,60));assert_eq!(z.0,z.1);for t in &e.tails[p][2]{assert!(avail(child_sig(s,p,t,e),e).is_empty())}z}

fn proc18(start:u64,end:u64,e:Arc<E>)->HStat{let mut f=File::open(H18_INPUT).unwrap();f.seek(SeekFrom::Start(80+80*start)).unwrap();let mut rd=BufReader::with_capacity(8<<20,f);let mut st=HStat::default();let mut plans:HashMap<SKey,Vec<Choice>>=HashMap::new();let mut term=HashMap::new();for index in start..end{let mut b=[0u8;80];rd.read_exact(&mut b).unwrap();let x=dh18(&b);assert_eq!(x.orbit as u32*x.stabilizer as u32,384);let s18=sig(&x.row,&e);let ps3=avail(s18,&e);let m3=ps3.len();assert!(m3>0&&x.weight%m3 as i128==0&&U%((x.m2 as usize*m3)as i128)==0);st.records+=1;st.uses+=x.uses;st.source+=x.weight;st.l1+=x.weight.abs();st.first_pivots+=m3 as u64;let mut witness=None;for p3 in ps3{let key=SKey{sig:s18,pivot:p3 as u8,degree:2};let cs=plans.entry(key).or_insert_with(||choices(s18,p3,2,&e)).clone();st.first_tails+=12;st.pivotable+=cs.len()as u64;for q in cs{let row20=replace(&x.row,&e.anchors[p3],&e.tails[p3][0][q.tail as usize]);assert_eq!(sig(&row20,&e),q.sig);let m4=q.pivots.len();assert_eq!(x.weight%(m3*m4)as i128,0);for p4 in q.pivots{st.final_pivots+=1;let z=terminal4(&row20,q.sig,p4,&e,&mut term,&mut st);let unit=x.weight/(m3*m4)as i128;st.terminal+=60;st.charge+=unit*z.0 as i128;*st.hist.entry((m3 as u8,m4 as u8)).or_default()+=1;if witness.is_none()&&z.0!=0{witness=Some(format!("source_D14_R2_2_2_4\tD14:222|R:2-2-2-4\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",x.weight,m3,m4,p3,q.tail,p4,unit,z.0,unit*z.0 as i128,hx(&row20)))}}}}if let Some(w)=witness{let j=bin(index,H18_N);st.samples.entry(j).or_insert((index,format!("{}\t{}\t{}",j,index,w)));}}st.peak=st.peak.max(term.len());st}

fn proc_pair(start:u64,end:u64,e:Arc<E>)->HStat{let mut f=File::open(PAIR_INPUT).unwrap();f.seek(SeekFrom::Start(80+53*start)).unwrap();let mut rd=BufReader::with_capacity(8<<20,f);let mut st=HStat::default();let mut plans:HashMap<SKey,Vec<Choice>>=HashMap::new();let mut term=HashMap::new();let mut prior=None;for index in start..end{let mut b=[0u8;53];rd.read_exact(&mut b).unwrap();let x=dpair(&b);assert!(prior.map_or(true,|z|z<x.key));prior=Some(x.key);assert_eq!(x.orbit as u32*x.stabilizer as u32,384);let s16=sig(&x.key.row,&e);let ps2=avail(s16,&e);assert!(ps2.contains(&(x.key.pivot as usize)));let m2=ps2.len();st.records+=1;st.uses+=x.uses;st.source+=x.weight;st.l1+=x.weight.abs();st.first_pivots+=1;let p2=x.key.pivot as usize;let key=SKey{sig:s16,pivot:x.key.pivot,degree:4};let cs=plans.entry(key).or_insert_with(||choices(s16,p2,4,&e)).clone();st.first_tails+=60;st.pivotable+=cs.len()as u64;let mut witness=None;for q in cs{let row20=replace(&x.key.row,&e.anchors[p2],&e.tails[p2][2][q.tail as usize]);assert_eq!(sig(&row20,&e),q.sig);let m3=q.pivots.len();assert_eq!(x.weight%m3 as i128,0);assert_eq!(U%((m2*m3)as i128),0);for p3 in q.pivots{st.final_pivots+=1;let z=terminal4(&row20,q.sig,p3,&e,&mut term,&mut st);let unit=-x.weight/m3 as i128;st.terminal+=60;st.charge+=unit*z.0 as i128;*st.hist.entry((m2 as u8,m3 as u8)).or_default()+=1;if witness.is_none()&&z.0!=0{witness=Some(format!("source_D14_R2_4_4\tD14:222|R:2-4-4\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",x.weight,m2,m3,p2,q.tail,p3,unit,z.0,unit*z.0 as i128,hx(&row20)))}}}if let Some(w)=witness{let j=bin(index,PAIR_N);st.samples.entry(j).or_insert((index,format!("{}\t{}\t{}",j,index,w)));}}st.peak=st.peak.max(term.len());st}

fn header(family:&str)->u64{if family=="hidden18"{let mut h=[0u8;80];File::open(H18_INPUT).unwrap().read_exact(&mut h).unwrap();assert_eq!(&h[..8],b"H18PIV2\0");assert_eq!(i128::from_le_bytes(h[8..24].try_into().unwrap()),U);assert_eq!(u16::from_le_bytes(h[28..30].try_into().unwrap()),80);assert_eq!(u64::from_le_bytes(h[48..56].try_into().unwrap()),H18_N);assert_eq!(metadata(H18_INPUT).unwrap().len(),80+80*H18_N);H18_N}else{let mut h=[0u8;80];File::open(PAIR_INPUT).unwrap().read_exact(&mut h).unwrap();assert_eq!(&h[..8],b"H16ORM1\0");assert_eq!(i128::from_le_bytes(h[8..24].try_into().unwrap()),U);assert_eq!(u16::from_le_bytes(h[28..30].try_into().unwrap()),53);assert_eq!(u64::from_le_bytes(h[48..56].try_into().unwrap()),PAIR_N);assert_eq!(metadata(PAIR_INPUT).unwrap().len(),80+53*PAIR_N);PAIR_N}}
pub fn run(){let a:Vec<_>=std::env::args().collect();let mut family="hidden18".to_string();let(mut start,mut count,mut workers)=(0u64,1u64,1usize);let mut output="/tmp/k24_charge_hidden.json".to_string();let mut i=1;while i<a.len(){match a[i].as_str(){"--family"=>{family=a[i+1].clone();i+=2},"--start"=>{start=a[i+1].parse().unwrap();i+=2},"--count"=>{count=a[i+1].parse().unwrap();i+=2},"--workers"=>{workers=a[i+1].parse().unwrap();i+=2},"--output"=>{output=a[i+1].clone();i+=2},_=>panic!("bad argument")}}assert!(["hidden18","hidden_pair"].contains(&family.as_str())&&(1..=8).contains(&workers)&&count>0);let total=header(&family);assert!(start<=total&&count<=total-start);let begun=Instant::now();let e=Arc::new(parse());let mut jobs=Vec::new();for w in 0..workers{let lo=start+count*w as u64/workers as u64;let hi=start+count*(w as u64+1)/workers as u64;let ee=e.clone();let ff=family.clone();jobs.push(thread::spawn(move||if ff=="hidden18"{proc18(lo,hi,ee)}else{proc_pair(lo,hi,ee)}))}let mut st=HStat::default();for j in jobs{st.add(j.join().unwrap())}assert_eq!(st.records,count);assert_eq!(st.terminal,60*st.final_pivots);assert_eq!(st.hits+st.misses,st.final_pivots);let elapsed=begun.elapsed().as_secs_f64();assert!(elapsed<600.0);let(gid,id,input,sha,sign)=if family=="hidden18"{("source_D14_R2_2_2_4","D14:222|R:2-2-2-4",H18_INPUT,H18_SHA,"retained w2; K2 selected-pivot and terminal K4 selected-pivot give +w2/(m3*m4)")}else{("source_D14_R2_4_4","D14:222|R:2-4-4",PAIR_INPUT,PAIR_SHA,"retained w2; terminal selected pivot gives -w2/m3")};let sample_path=format!("{}.samples.tsv",output);let mut lines=vec!["sample_bin\tsource_index\tgroup_id\tlineage_id\tretained_weight_scaled_U\tm_prev\tm_final\tpreterminal_pivot\tpreterminal_tail\tterminal_pivot\tunit_scaled_U\tterminal_K4_charge\tcontribution_scaled_U\tK20_row".to_string()];lines.extend(st.samples.values().map(|x|x.1.clone()));let q=format!("{}.tmp",sample_path);std::fs::write(&q,format!("{}\n",lines.join("\n"))).unwrap();rename(q,&sample_path).unwrap();let text=format!("{{\n  \"status\":\"PASS_BOUNDED_K24_CHARGE_ONLY_HIDDEN\",\n  \"degree\":24,\n  \"family\":\"{}\",\n  \"group_id\":\"{}\",\n  \"ids\":[\"{}\"],\n  \"scale_U\":\"{}\",\n  \"input\":\"{}\",\n  \"input_sha256_expected\":\"{}\",\n  \"input_interval\":[{},{}],\n  \"input_records\":{},\n  \"retained_uses\":{},\n  \"retained_weight_sum_scaled_U\":\"{}\",\n  \"retained_weight_l1_scaled_U\":\"{}\",\n  \"first_selected_pivots\":{},\n  \"first_tail_evaluations\":{},\n  \"pivotable_K20_children\":{},\n  \"terminal_selected_pivots\":{},\n  \"terminal_K24_occurrences\":{},\n  \"full_occurrences\":{},\n  \"irreducible_occurrences\":{},\n  \"full_charge_scaled_U\":\"{}\",\n  \"irreducible_charge_scaled_U\":\"{}\",\n  \"denominator_hist\":{{{}}},\n  \"terminal_cache\":{{\"hits\":{},\"misses\":{},\"clears\":{},\"peak_keys_per_worker\":{},\"hard_cap\":{}}},\n  \"literal_witnesses\":{},\n  \"literal_witness_ledger\":\"{}\",\n  \"sign_rule\":\"{}\",\n  \"all_terminal_responses_exhaustive\":true,\n  \"full_equals_irreducible\":true,\n  \"workers\":{},\n  \"elapsed_seconds\":{:.6},\n  \"linear_full_projection_seconds\":{:.6},\n  \"scope\":\"exact hidden-ledger charge-only bounded fold; no K24 rows, B records, relative Gram, or verdict\"\n}}\n",family,gid,id,U,input,sha,start,start+count,count,st.uses,st.source,st.l1,st.first_pivots,st.first_tails,st.pivotable,st.final_pivots,st.terminal,st.terminal,st.terminal,st.charge,st.charge,hmap(&st.hist),st.hits,st.misses,st.clears,st.peak,CACHE_CAP,st.samples.len(),sample_path,sign,workers,elapsed,elapsed*total as f64/count as f64);let tmp=format!("{}.tmp",output);std::fs::write(&tmp,&text).unwrap();rename(tmp,&output).unwrap();print!("{}",text)}
}
fn main(){fold::run()}
